#!/usr/bin/env python3
"""Generates src/apply.html and src/onboarding.html (decision screens)."""
import html
def mini(steps, wid):
    out=[f'<div class="mini" data-wizard id="{wid}"><div class="row between"><span class="tiny muted" data-count></span><span class="tiny gold" data-step-label></span></div><div class="steps" style="margin:6px 0 10px"></div>']
    for title, body, who in steps:
        out.append(f'<div class="wstep" data-label="{html.escape(who)}"><h4 style="margin-bottom:8px">{title}</h4>{body}</div>')
    out.append('<div class="row" style="margin-top:12px"><button class="btn sm line" data-prev>Back</button><button class="btn sm grow" data-next>Next step</button></div></div>')
    return '\n'.join(out)

F=lambda l,v:f'<div class="field"><label class="f">{l}</label><input class="inp" value="{v}"></div>'
company=('Company info', F('Legal name','Bluewater Flooring LLC (sample)')+F('Owner / contact','Sam Rivera · sam@bluewater.example')+F('Years in business','6'), 'Contractor')
trades=('Trades &amp; regions','<label class="f">Trades</label><div class="opts" data-multi><button class="on">Flooring</button><button>Drywall</button><button>Paint</button><button>Plumbing</button><button>Electrical</button><button>HVAC</button></div><label class="f" style="margin-top:10px">Coverage</label><div class="opts" data-multi><button class="on">King</button><button class="on">Pierce</button><button>Snohomish</button><button>Multnomah</button><button>Ada</button></div><p class="tiny muted" style="margin-top:8px">Capacity: 2 jobs at once · emergency on-call: no</p>','Contractor')
docs=('Insurance certificate &amp; W-9','<button class="drop" style="width:100%" data-add-file="#FID">⇪ Upload certificate of insurance</button><div class="stack s8" id="FID" style="margin-top:8px"><div class="file"><span class="ic">PDF</span><span class="grow">COI_sample.pdf</span><span class="chip ok">uploaded</span></div><div class="file"><span class="ic">PDF</span><span class="grow">W-9_sample.pdf</span><span class="chip ok">uploaded</span></div></div><p class="tiny muted" style="margin-top:6px">State registration is entered privately and checked by IVO; it\'s never shown to customers.</p>','Contractor')
def refs(n): return ('References',''.join(F(f'Reference {i+1}',v) for i,v in enumerate(['Property manager · ref1@example.com','General contractor · ref2@example.com'][:n]))+f'<p class="tiny muted">{n} required. IVO contacts them.</p>','Contractor')
check=('Compliance check','<div class="list small" style="background:#fff;border:1px solid var(--line);border-radius:8px"><div class="li"><span class="dot ok"></span><span class="grow">State registration lookup</span><span class="chip ok">active</span></div><div class="li"><span class="dot ok"></span><span class="grow">Certificate limits &amp; IVO named</span><span class="chip ok">ok</span></div><div class="li"><span class="dot ok"></span><span class="grow">W-9 name matches</span><span class="chip ok">ok</span></div><div class="li"><span class="dot warn"></span><span class="grow">References</span><span class="chip warn">1 of 2 replied</span></div></div><p class="tiny muted" style="margin-top:6px">Rules flag gaps; a person decides.</p>','IVO staff')
approve=('Approval','<div class="sheet small" style="background:#fff"><b>Approve Bluewater Flooring LLC?</b><p class="muted" style="margin:4px 0 8px">Flooring · King, Pierce · all documents verified</p><div class="row" data-item><span class="chip" data-status hidden></span><button class="btn sm ok" data-set="Approved|ok">Approve</button><button class="btn sm ghost" data-set="Declined with reason|bad">Decline</button></div></div><p class="tiny muted" style="margin-top:6px">Owner or admin only. Logged in the audit trail.</p>','Owner')
onboard=('Onboarding','<div class="list small" style="background:#fff;border:1px solid var(--line);border-radius:8px"><div class="li"><span class="dot ok"></span><span class="grow">Sign subcontractor agreement</span></div><div class="li"><span class="dot ok"></span><span class="grow">Add crew &amp; install the app</span></div><div class="li"><span class="dot ok"></span><span class="grow">Read “How IVO jobs work” (10 min)</span></div><div class="li"><span class="dot ok"></span><span class="grow">Status → Ready for routing</span></div></div><a class="btn sm block" style="margin-top:10px" href="../contractor/index.html#opps">See the contractor app →</a>','Contractor')
def fix(step,fid): return (step[0],step[1].replace('FID',fid),step[2])

A=[('IVO invites the contractor','<div class="sheet small" style="background:#fff"><b>Email from IVO</b><p class="muted" style="margin-top:4px">“Dana at IVO Group invited Bluewater Flooring LLC to apply to IVO\'s contractor network.”</p><a class="btn sm" style="margin-top:8px" data-goto="1" href="#">Accept invitation</a></div><p class="tiny muted" style="margin-top:8px">IVO staff choose who to invite: contractors they know, met on jobs, or found in public directories.</p>','IVO staff'),
   ('Sign in with email code','<div class="otp" style="gap:4px"><input value="2"><input value="0"><input value="4"><input value="8"><input value="1"><input value="6"></div><p class="tiny muted" style="margin-top:8px;text-align:center">No passwords. Same sign-in as the apps.</p>','Contractor'),
   company,trades,fix(docs,'fa'),refs(1),check,approve,onboard]
B=[('Open application form','<div class="sheet small" style="background:#fff"><b>Partner with IVO</b><p class="muted" style="margin-top:4px">Public form on the website. Anyone can apply.</p></div>'+F('Company','Bluewater Flooring LLC (sample)')+F('Email','sam@bluewater.example'),'Contractor'),
   ('Verify email','<div class="otp" style="gap:4px"><input value="2"><input value="0"><input value="4"><input value="8"><input value="1"><input value="6"></div><p class="tiny muted" style="margin-top:8px;text-align:center">Creates an applicant account with no access to jobs.</p>','Contractor'),
   trades,fix(docs,'fb'),refs(2),('Document verification',check[1],'IVO staff'),
   ('Trial job','<div class="sheet small" style="background:#fff"><b>Trial: REQ-1049 · LVP repair, 1 unit</b><p class="muted" style="margin-top:4px">Small job, IVO checks in on site, extra photos at closeout.</p><span class="chip info" style="margin-top:6px">Scorecard after trial: 4.7</span></div>','IVO staff + contractor'),
   approve,onboard]
C=[('Someone refers the contractor','<div class="sheet small" style="background:#fff"><b>Referral from Evergreen Restoration Co.</b><p class="muted" style="margin-top:4px">“Bluewater did our flooring on 3 jobs. Reliable.”</p></div><p class="tiny muted" style="margin-top:8px">Referrals come from network contractors or customers.</p>','Referrer'),
   ('IVO reviews the referral','<div class="sheet small" style="background:#fff"><p>Referrer in good standing (4.8). Trade gap: flooring in Pierce.</p><div class="row" style="margin-top:8px" data-item><span class="chip" data-status hidden></span><button class="btn sm ok" data-set="Invite approved|ok">Approve invite</button></div></div>','IVO staff'),
   company,trades,fix(docs,'fc'),('References','<div class="sheet small" style="background:#fff">Referrer counts as reference 1.</div>'+F('Reference 2','General contractor · ref2@example.com'),'Contractor'),
   check,approve,onboard]

def col(key,title,sub,pros,cons,steps,wid,status='',fit=''):
    chips={'approved':'<span class="chip ok">Approved by owner 2026-11-13</span>','not-chosen':'<span class="chip">Not chosen</span>','later':'<span class="chip later">Later</span>','allowed':'<span class="chip info">Allowed for existing accounts</span>'}
    cls={'approved':' rec approved','not-chosen':' not-chosen','later':' later-opt','allowed':' allowed'}.get(status,'')
    chip=chips.get(status,'')
    return f'''<div class="opt-col{cls}"><div class="oh"><div class="row between"><span class="k">OPTION {key}</span>{chip}</div><h3 style="margin-top:4px">{title}</h3><p class="small muted">{sub}</p></div>
<div class="ob stack">{mini(steps,wid)}
<div class="grid g2" style="gap:8px"><div><div class="tiny muted">Good</div><ul class="pc pros">{''.join(f"<li>{p}</li>" for p in pros)}</ul></div><div><div class="tiny muted">Watch</div><ul class="pc cons">{''.join(f"<li>{c}</li>" for c in cons)}</ul></div></div>{fit}</div></div>'''

apply=f'''<!--meta title="Contractor application: decision" out="apply/index.html"-->
<div class="land-h" style="padding:30px 24px 34px"><div class="wrap"><a class="row small" href="../index.html" style="color:var(--gold-l);margin-bottom:12px">← Prototype home</a><div class="eyebrow" style="color:var(--gold-l)">Decision recorded</div><h1>How should contractors <em>join</em> IVO's network?</h1><p style="max-width:760px;margin-top:10px">The owner approved option A on 13 Nov 2026. Click through each flow. All three end in the same checks (insurance certificate, W-9, state registration lookup, references), your approval and onboarding. Sample data only.</p></div></div>
<div class="wrap" style="padding:24px 16px 60px">
<div class="opt-cols">
{col('A','Invite-only, staff-vetted','IVO staff invite contractors they choose, after vetting. Nobody joins unasked. First job is a watched trial.',['Matches the invite-only rule and the locked launch scope','Fast to build: reuses the invite and sign-in already planned','IVO controls quality from day one'],['Network grows only as fast as staff recruit','Contractors who find IVO on their own need a staff follow-up'],A,'wa','approved','<div class="note"><b>Approved by owner 2026-11-13.</b> Invite-only after staff vetting, with a closely watched trial first job. The existing “Partner with IVO” form stays as an inquiry that lands in Triage; staff decide whether to invite.</div>')}
{col('B','Open application → verification → trial job','Anyone can apply on the website; documents are verified, then a trial job.',['Biggest pipeline of contractors','Trial job proves quality before real volume'],['Needs a public applicant account: the locked scope keeps public self-serve out','More staff time screening unsuitable applicants','More spam and fraud exposure (needs bot protection)'],B,'wb','not-chosen')}
{col('C','Referral-based','Contractors join when a trusted contractor or customer refers them.',['High trust: someone vouches for them','Very little screening noise'],['Slow when IVO is starting from zero: few people to refer','Can narrow the network to one circle'],C,'wc','not-chosen','<div class="note">Not chosen for launch. Could work <b>later</b> as an extra source once the network has 15–20 good contractors. Same invite mechanism as A.</div>')}
</div>
<div class="decision rec" style="margin-top:20px"><h3>Recorded 13 Nov 2026</h3><p class="small" style="margin-top:8px">The owner approved <b>option A</b>: invite-only after staff vetting, with a watched trial first job. The Partner with IVO form stays as an inquiry that lands in Triage; staff decide whether to invite. Options B and C were not chosen.</p><p class="small" style="margin-top:8px">Still open: how many references to require (1 or 2), and who besides the owner can approve a contractor (a second admin).</p></div>
</div>'''
open('src/apply.html','w').write(apply)

O1=[('Customer sends a request','<div class="sheet small" style="background:#fff"><b>Request form (website)</b><p class="muted" style="margin-top:4px">Trade, location, scope, urgency, budget, photos, files. No account needed.</p></div>'+F('Email','maya.ortiz@harborline.example'),'Customer'),
    ('Confirmation email','<div class="sheet small" style="background:#fff"><b>“We received REQ-1059”</b><p class="muted" style="margin-top:4px">What happens next, coordinator name, emergency line. Updates by email until they\'re invited.</p></div>','System'),
    ('IVO reviews &amp; calls','<div class="sheet small" style="background:#fff">Triage in the staff console: type, trade, tier, owner. Coordinator confirms scope by phone or email.</div><a class="btn sm line block" style="margin-top:8px" href="../console/index.html#triage">See triage →</a>','IVO staff'),
    ('Approve the invite','<div class="sheet small" style="background:#fff"><b>Invite Maya Ortiz to a Harborline workspace?</b><div class="row" style="margin-top:8px" data-item><span class="chip" data-status hidden></span><button class="btn sm ok" data-set="Invite sent|ok">Approve invite</button></div></div><p class="tiny muted" style="margin-top:6px">A person approves every new customer workspace.</p>','IVO staff'),
    ('Accept &amp; sign in','<div class="sheet small" style="background:#fff">Invite email → email code → their request is already inside.</div><a class="btn sm block" style="margin-top:8px" href="../customer/index.html#invite">See it in the customer app →</a>','Customer'),
    ('Set up the company','<div class="list small" style="background:#fff;border:1px solid var(--line);border-radius:8px"><div class="li">Add properties</div><div class="li">Invite colleagues (IVO confirms)</div><div class="li">Set approval limits</div></div>','Customer')]
O2=[('IVO creates the account','<div class="sheet small" style="background:#fff">Staff set up the company, properties and first contact for a customer IVO already works with (or a signed account).</div>','IVO staff'),
    ('Approve the invite',O1[3][1],'Owner / admin'),
    ('Accept &amp; sign in','<div class="sheet small" style="background:#fff">Invite email → email code → empty workspace with their properties.</div>','Customer'),
    ('First request in the app','<div class="sheet small" style="background:#fff">They submit their first request from the app instead of the website.</div><a class="btn sm block" style="margin-top:8px" href="../customer/index.html#new">See the request wizard →</a>','Customer')]
O3=[('Customer sends a request',O1[0][1],'Customer'),
    ('Private tracker link','<div class="sheet small" style="background:#fff"><b>Track REQ-1059</b><p class="muted" style="margin-top:4px">A status page reachable by a private link in the email. No account.</p><ol class="tl" style="margin-top:6px"><li class="done">Received</li><li class="now">IVO review</li><li>Scheduled</li></ol></div>','Customer'),
    ('Invite on approval','<div class="sheet small" style="background:#fff">Once they approve a quote, IVO invites them to the full workspace.</div>','IVO staff'),
    ('Accept &amp; sign in',O1[4][1],'Customer')]
onb=f'''<!--meta title="Customer onboarding: decision" out="onboarding/index.html"-->
<div class="land-h" style="padding:30px 24px 34px"><div class="wrap"><a class="row small" href="../index.html" style="color:var(--gold-l);margin-bottom:12px">← Prototype home</a><div class="eyebrow" style="color:var(--gold-l)">Decision recorded</div><h1>How do customers <em>get into</em> the portal?</h1><p style="max-width:760px;margin-top:10px">The portal is invite-only. The owner approved option 1 on 13 Nov 2026: request first, then an invite after IVO reviews it. Click through each flow. Sample data only.</p></div></div>
<div class="wrap" style="padding:24px 16px 60px">
<div class="opt-cols">
{col('1','Request first, then invite','New customers send a request on the website; after IVO reviews it, they\'re invited to the portal.',['No account friction for a first-time customer','IVO screens every customer before portal access','The request is already waiting in their workspace'],['Updates go by email until the invite is accepted'],O1,'o1','approved','<div class="note"><b>Approved by owner 2026-11-13.</b> New customers request first and are invited after IVO review. Staff can still use option 2 for accounts IVO already knows: same invite, no extra build.</div>')}
{col('2','Account first (staff-invited)','IVO sets up accounts for customers it already works with before any request.',['Great for property managers with many buildings','Properties and approvers ready before the first job'],['Doesn\'t work for new website leads on its own'],O2,'o2','allowed','<div class="note">Allowed for existing accounts. Staff can create the workspace and send the invite without a new website request.</div>')}
{col('3','Request first + private tracker link','Like option 1, plus a no-login status page per request until they\'re invited.',['Customer sees progress right away'],['Extra public page to build and secure (link-based access)','Outside the locked launch scope: <b>Later</b>'],O3,'o3','later','<div class="note">Stays marked <b>Later</b>. Possible add-on to option 1 after launch.</div>')}
</div>
<div class="decision rec" style="margin-top:20px"><h3>Recorded 13 Nov 2026</h3><p class="small" style="margin-top:8px">The owner approved <b>option 1</b>: new customers send a request first and are invited after IVO reviews it. Option 2 stays allowed for existing accounts (staff-created). Option 3 stays marked Later.</p><p class="small" style="margin-top:8px">Still open: who can approve a new customer workspace, and the role matrix.</p></div>
</div>'''
open('src/onboarding.html','w').write(onb)
print('ok')
